48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        owner.setCity(canonicalCity(owner.getCity()));
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        if (isDailyRegistrationLimitReached()) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (isCityCapacityReached(owner.getCity())) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
122	        owner.setMembershipNumber(membershipNumber);
123	        owner.setCustomerCode(customerCode(owner));
124	        owner.setMembershipTier(membershipNumber <= 100 ? "FOUNDING" : "STANDARD");
125	        owner.setNamesakeCount(namesakeCount(owner));
126	        owner.setSharesHousehold(sharesHousehold(owner));
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        currentOwner.setAddress(ownerFieldsDto.getAddress());
142	        currentOwner.setCity(ownerFieldsDto.getCity());
143	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
144	        currentOwner.setLastName(ownerFieldsDto.getLastName());
145	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
146	        this.clinicService.saveOwner(currentOwner);
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Transactional
152	    @Override
153	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        this.clinicService.deleteOwner(owner);
159	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        HttpHeaders headers = new HttpHeaders();
170	        Pet pet = petMapper.toPet(petFieldsDto);
171	        owner.setId(ownerId);
172	        pet.setOwner(owner);
173	        pet.getType().setName(null);
174	        this.clinicService.savePet(pet);
175	        PetDto petDto = petMapper.toPetDto(pet);
176	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
177	            .buildAndExpand(pet.getId()).toUri());
178	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner != null) {
186	            Pet currentPet = this.clinicService.findPetById(petId);
187	            if (currentPet != null) {
188	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
189	                currentPet.setName(petFieldsDto.getName());
190	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
191	                this.clinicService.savePet(currentPet);
192	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	            }
194	        }
195	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
201	        HttpHeaders headers = new HttpHeaders();
202	        Visit visit = visitMapper.toVisit(visitFieldsDto);
203	        Pet pet = new Pet();
204	        pet.setId(petId);
205	        visit.setPet(pet);
206	        this.clinicService.saveVisit(visit);
207	        VisitDto visitDto = visitMapper.toVisitDto(visit);
208	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
209	            .buildAndExpand(visit.getId()).toUri());
210	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
211	    }
212	
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
217	        Owner owner = this.clinicService.findOwnerById(ownerId);
218	        if (owner != null) {
219	            Pet pet = owner.getPet(petId);
220	            if (pet != null) {
221	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    /**
228	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
229	     * owner using the same telephone number.
230	     *
231	     * @param owner the candidate owner to check
232	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
233	     */
234	    /**
235	     * Builds the customer code assigned to a newly created owner, formatted as
236	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
237	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
238	     *
239	     * @param owner the owner being created
240	     * @return the customer code for the owner
241	     */
242	    /**
243	     * Counts how many other owners already share the given owner's last name at the moment of
244	     * creation. The owner being created is not yet persisted and so is not included in the count.
245	     *
246	     * @param owner the owner being created
247	     * @return the number of existing owners with the same last name
248	     */
249	    /**
250	     * Determines whether the newly created owner shares a household with an existing owner, i.e.
251	     * whether another owner already has the same address and city. Both values are matched
252	     * case- and whitespace-insensitively.
253	     *
254	     * @param owner the owner being created
255	     * @return {@code true} if another owner already has the same address and city, {@code false} otherwise
256	     */
257	    private boolean sharesHousehold(Owner owner) {
258	        String address = normalize(owner.getAddress());
259	        String city = normalize(owner.getCity());
260	        return this.clinicService.findAllOwners().stream()
261	            .anyMatch(existing -> Objects.equals(address, normalize(existing.getAddress()))
262	                && Objects.equals(city, normalize(existing.getCity())));
263	    }
264	
265	    private int namesakeCount(Owner owner) {
266	        String lastName = owner.getLastName();
267	        return (int) this.clinicService.findAllOwners().stream()
268	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
269	            .count();
270	    }
271	
272	    private String customerCode(Owner owner) {
273	        String city = owner.getCity();
274	        long existingInCity = this.clinicService.findAllOwners().stream()
275	            .filter(existing -> Objects.equals(existing.getCity(), city))
276	            .count();
277	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
278	    }
279	
280	    /**
281	     * Determines the canonical spelling of the city for a newly created owner. If another owner
282	     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
283	     * spelling of the city name is reused so that all owners in a city share a consistent value.
284	     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
285	     *
286	     * @param city the raw city as supplied when creating the owner, may be {@code null}
287	     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
288	     */
289	    private String canonicalCity(String city) {
290	        if (city == null) {
291	            return null;
292	        }
293	        String normalized = normalize(city);
294	        for (Owner existing : this.clinicService.findAllOwners()) {
295	            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
296	                return existing.getCity();
297	            }
298	        }
299	        return titleCase(city);
300	    }
301	
302	    /**
303	     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
304	     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
305	     * {@code "new  YORK city"} becomes {@code "New York City"}).
306	     *
307	     * @param value the value to title-case
308	     * @return the title-cased value
309	     */
310	    private static String titleCase(String value) {
311	        StringBuilder result = new StringBuilder();
312	        for (String word : value.strip().split("\\s+")) {
313	            if (word.isEmpty()) {
314	                continue;
315	            }
316	            if (result.length() > 0) {
317	                result.append(' ');
318	            }
319	            result.append(Character.toUpperCase(word.charAt(0)))
320	                .append(word.substring(1).toLowerCase(Locale.ROOT));
321	        }
322	        return result.toString();
323	    }
324	
325	    /**
326	     * Determines whether the maximum number of owners allowed to be registered on a single day has
327	     * already been reached. At most 20 owners may be created with today's registration date; once
328	     * that many exist, further registrations for today are rejected.
329	     *
330	     * @return {@code true} if 20 or more owners already have today's registration date
331	     */
332	    private boolean isDailyRegistrationLimitReached() {
333	        LocalDate today = LocalDate.now();
334	        long registeredToday = this.clinicService.findAllOwners().stream()
335	            .filter(existing -> today.equals(existing.getRegistrationDate()))
336	            .count();
337	        return registeredToday >= 20;
338	    }
339	
340	    /**
341	     * Determines whether the city of a newly created owner has already reached its capacity. At most
342	     * 8 owners may live in a single city; once a city already contains 8 owners, further registrations
343	     * for that city are rejected. Cities are matched case- and whitespace-insensitively so that
344	     * differing spellings of the same city name count towards the same limit.
345	     *
346	     * @param city the canonical city of the owner being created, may be {@code null}
347	     * @return {@code true} if the city already contains 8 or more owners, {@code false} otherwise
348	     */
349	    private boolean isCityCapacityReached(String city) {
350	        String normalized = normalize(city);
351	        long existingInCity = this.clinicService.findAllOwners().stream()
352	            .filter(existing -> Objects.equals(normalized, normalize(existing.getCity())))
353	            .count();
354	        return existingInCity >= 8;
355	    }
356	
357	    private boolean isDuplicateOwner(Owner owner) {
358	        return this.clinicService.findAllOwners().stream()
359	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
360	    }
361	
362	    /**
363	     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
364	     * any other non-digit characters). This is applied before storing the number and before the
365	     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
366	     * stored identically and treated as the same number.
367	     *
368	     * @param telephone the raw telephone number, may be {@code null}
369	     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
370	     */
371	    private static String normalizeTelephone(String telephone) {
372	        if (telephone == null) {
373	            return null;
374	        }
375	        return telephone.replaceAll("[^0-9]", "");
376	    }
377	
378	    /**
379	     * Determines whether the given owner's email address is already used by another owner. An owner
380	     * without an email address never conflicts. The comparison is case-insensitive and ignores
381	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
382	     * {@code "john.smith@example.com"} are treated as the same address.
383	     *
384	     * @param owner the candidate owner to check
385	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
386	     */
387	    private boolean isDuplicateEmail(Owner owner) {
388	        String email = normalize(owner.getEmail());
389	        if (email == null || email.isEmpty()) {
390	            return false;
391	        }
392	        return this.clinicService.findAllOwners().stream()
393	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
394	    }
395	
396	    /**
397	     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
398	     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
399	     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
400	     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
401	     *
402	     * @param value the raw value, may be {@code null}
403	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
404	     */
405	    private static String normalize(String value) {
406	        if (value == null) {
407	            return null;
408	        }
409	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
410	    }
411	}
